use std::collections::BTreeSet;
use crate::grounding::{Action,State};
use crate::search;
type Mutex=BTreeSet<(usize,usize)>;
fn pair(a:usize,b:usize)->(usize,usize){
    (a.min(b),a.max(b))
}
fn compatible(pre:&State,mutex:&Mutex)->bool{
    pre.iter().all(|&p|pre.iter().all(|&q|p==q||!mutex.contains(&pair(p,q))))
}
#[derive(Clone)] struct Element{
    action:Option<usize>,
    pre:State,
    add:State,
    del:State
}
#[derive(Clone)] struct Level{
    elements:Vec<Element>,
    mutex:Mutex
}
struct Extractor{
    levels:Vec<Level>,
    memo:BTreeSet<(usize,Vec<usize>)>,
    searched:usize,
    hits:usize,
    tried:usize
}
impl Extractor{
    fn extract(&mut self,j:usize,goals:Vec<usize>)->Option<Vec<Vec<usize>>>{
        if j==0{
            return Some(Vec::new());
        }
        if self.memo.contains(&(j,goals.clone())){
            self.hits+=1;
            return None;
        }
        self.searched+=1;
        let result=self.assign(j,&goals,0,Vec::new());
        if result.is_none(){
            self.memo.insert((j,goals));
        }
        result
    }
    fn assign(&mut self,j:usize,goals:&[usize],mut k:usize,chosen:Vec<usize>)->Option<Vec<Vec<usize>>>{
        let level=self.levels[j-1].clone();
        while k<goals.len()&&chosen.iter().any(|&x|level.elements[x].add.contains(&goals[k])){
            k+=1;
        }
        if k==goals.len(){
            let previous:State=chosen.iter().flat_map(|&x|level.elements[x].pre.iter().copied()).collect();
            let mut plan=self.extract(j-1,previous.into_iter().collect())?;
            let mut actions:Vec<_>=chosen.iter().filter_map(|&x|level.elements[x].action).collect();
            actions.sort();
            plan.push(actions);
            return Some(plan);
        }
        let goal=goals[k];
        let mut achievers:Vec<_>=level.elements.iter().enumerate().filter(|(_,e)|e.add.contains(&goal)).map(|(i,_)|i).collect();
        achievers.sort_by_key(|&i|(level.elements[i].action.is_some(),level.elements[i].action.unwrap_or(0)));
        for x in achievers{
            if chosen.iter().all(|&y|x==y||!level.mutex.contains(&pair(x,y))){
                self.tried+=1;
                let mut next=chosen.clone();
                next.push(x);
                if let Some(plan)=self.assign(j,goals,k+1,next){
                    return Some(plan);
                }
            }
        }
        None
    }
}
pub struct Result{
    pub search:search::Result,
    pub layers:Vec<Vec<usize>>,
    pub records:Vec<String>,
    pub hits:usize
}
pub fn run(actions:&[Action],initial:&State,goals:&State,limit:usize)->Result{
    let mut extractor=Extractor{
        levels:Vec::new(),
        memo:BTreeSet::new(),
        searched:0,
        hits:0,
        tried:0
    };
    let mut facts=initial.clone();
    let mut mutex=Mutex::new();
    let(mut previous_counts,mut records,mut answer,mut status)=(None,Vec::new(),Vec::new(),"level limit");
    for i in 0..=limit{
        records.push(format!("fact level {}: facts={} mutexes={}",i,facts.len(),mutex.len()));
        let extract=goals.is_subset(&facts)&&compatible(goals,&mutex);
        if extract{
            let before=extractor.searched;
            let hits=extractor.hits;
            let result=extractor.extract(i,goals.iter().copied().collect());
            records.push(format!("extract level {}: {} searched={} memo_hits={}",i,if result.is_some(){
                "success"
            }else{
                "fail"
            },extractor.searched-before,extractor.hits-hits));
            if let Some(plan)=result{
                answer=plan;
                status="solved";
                break;
            }
        }else if previous_counts==Some((facts.len(),mutex.len())){
            status="unreachable";
            break;
        }
        if i==limit{
            break;
        }
        previous_counts=Some((facts.len(),mutex.len()));
        let mut elements:Vec<_>=actions.iter().enumerate().filter(|(_,a)|a.pre.is_subset(&facts)&&compatible(&a.pre,&mutex)).map(|(i,a)|Element{
            action:Some(i),
            pre:a.pre.clone(),
            add:a.add.clone(),
            del:a.del.clone()
        }).collect();
        let real=elements.len();
        for &p in &facts{
            let singleton=[p].iter().copied().collect();
            elements.push(Element{
                action:None,
                pre:singleton,
                add:[p].iter().copied().collect(),
                del:State::new()
            });
        }
        let mut action_mutex=Mutex::new();
        for x in 0..elements.len(){
            for y in x+1..elements.len(){
                let(a,b)=(&elements[x],&elements[y]);
                let interference=!a.del.is_disjoint(&b.pre)||!a.del.is_disjoint(&b.add)||!b.del.is_disjoint(&a.pre)||!b.del.is_disjoint(&a.add);
                let competing=a.pre.iter().any(|&p|b.pre.iter().any(|&q|p!=q&&mutex.contains(&pair(p,q))));
                if interference||competing{
                    action_mutex.insert((x,y));
                }
            }
        }
        records.push(format!("action level {}: actions={} noops={} mutexes={}",i,real,facts.len(),action_mutex.len()));
        let next:State=elements.iter().flat_map(|e|e.add.iter().copied()).collect();
        let values:Vec<_>=next.iter().copied().collect();
        let mut next_mutex=Mutex::new();
        for x in 0..values.len(){
            for y in x+1..values.len(){
                let(p,q)=(values[x],values[y]);
                let impossible=elements.iter().enumerate().filter(|(_,e)|e.add.contains(&p)).all(|(a,_)|elements.iter().enumerate().filter(|(_,e)|e.add.contains(&q)).all(|(b,_)|a!=b&&action_mutex.contains(&pair(a,b))));
                if impossible{
                    next_mutex.insert((p,q));
                }
            }
        }
        extractor.levels.push(Level{
            elements,
            mutex:action_mutex
        });
        facts=next;
        mutex=next_mutex;
    }
    let plan=answer.iter().flat_map(|v|v.iter().copied()).collect();
    Result{
        search:search::Result{
            status,
            plan,
            expanded:extractor.searched,
            generated:extractor.tried
        },
        layers:answer,
        records,
        hits:extractor.hits
    }
}

use std::collections::{BTreeMap,BTreeSet};
use crate::pddl_parser::{Domain,Problem,Atom};
pub type State=BTreeSet<usize>;
#[derive(Clone)] pub struct Action{
    pub source:usize,
    pub name:String,
    pub args:Vec<String>,
    pub cost:i64,
    pub pre:State,
    pub neg:State,
    pub add:State,
    pub del:State
}
impl Action{
    pub fn text(&self)->String{
        Atom{
            predicate:self.name.clone(),
            terms:self.args.clone()
        }.text()
    }
}
pub struct Grounding{
    pub facts:Vec<Atom>,
    pub actions:Vec<Action>,
    pub initial:State,
    pub goals:State,
    pub unreachable:Vec<Atom>,
    pub stats:Vec<[usize;3]>,
    pub fluent:BTreeSet<String>,
    pub static_count:usize
}
pub fn subtype(d:&Domain,t:&str,u:&str)->bool{
    let mut current=t.to_string();
    loop {
        if current==u { return true; }
        if let Some(parent)=d.parents.get(&current) { current=parent.clone(); }
        else { return false; }
    }
}

pub fn fluents(d:&Domain)->BTreeSet<String>{
    d.actions.iter().flat_map(|a|a.effects.iter().map(|l|l.atom.predicate.clone())).collect()
}
struct Candidate{
    source:usize,
    args:Vec<String>,
    pre:BTreeSet<Atom>,
    neg:BTreeSet<Atom>,
    add:BTreeSet<Atom>,
    del:BTreeSet<Atom>
}
pub fn ground(d:&Domain,p:&Problem)->Grounding{
    fn combinations(choices:&[Vec<String>],i:usize,current:&mut Vec<String>,all:&mut Vec<Vec<String>>){
        if i==choices.len(){
            all.push(current.clone());
            return;
        }
        for x in &choices[i]{
            current.push(x.clone());
            combinations(choices,i+1,current,all);
            current.pop();
        }
    }
    let fluent=fluents(d);
    let initial:BTreeSet<_>=p.initial.iter().cloned().collect();
    let mut stats=vec![[0;3];d.actions.len()];
    let mut candidates=Vec::new();
    for(source,a)in d.actions.iter().enumerate(){
        let choices:Vec<Vec<String>>=a.parameters.iter().map(|(_,t)|p.objects.iter().filter(|(_,u)|subtype(d,u,t)).map(|(n,_)|n.clone()).collect()).collect();
        let mut all=Vec::new();
        combinations(&choices,0,&mut Vec::new(),&mut all);
        stats[source][0]=all.len();
        for args in all{
            let values:BTreeMap<_,_>=a.parameters.iter().map(|(n,_)|n.clone()).zip(args.iter().cloned()).collect();
            let mut c=Candidate{
                source,
                args,
                pre:BTreeSet::new(),
                neg:BTreeSet::new(),
                add:BTreeSet::new(),
                del:BTreeSet::new()
            };
            let mut valid=true;
            for l in &a.pre{
                let atom=l.atom.replace(&values);
                if atom.predicate=="="||!fluent.contains(&atom.predicate){
                    let truth=if atom.predicate=="="{
                        atom.terms[0]==atom.terms[1]
                    }else{
                        initial.contains(&atom)
                    };
                    if truth==l.negative{
                        valid=false;
                        break;
                    }
                }else if l.negative{
                    c.neg.insert(atom);
                }else{
                    c.pre.insert(atom);
                }
            }
            if !valid{
                continue;
            }
            for l in &a.effects{
                let atom=l.atom.replace(&values);
                if l.negative{
                    c.del.insert(atom);
                }else{
                    c.add.insert(atom);
                }
            }
            c.del=c.del.difference(&c.add).cloned().collect();
            stats[source][1]+=1;
            candidates.push(c);
        }
    }
    let mut reachable:BTreeSet<_>=initial.iter().filter(|a|fluent.contains(&a.predicate)).cloned().collect();
    let mut kept=BTreeSet::new();
    loop{
        let before=kept.len();
        for(i,c)in candidates.iter().enumerate(){
            if c.pre.is_subset(&reachable){
                kept.insert(i);
                reachable.extend(c.add.iter().cloned());
            }
        }
        if kept.len()==before{
            break;
        }
    }
    let predicates:BTreeMap<_,_>=d.predicates.iter().enumerate().map(|(i,p)|(p.name.clone(),i)).collect();
    let objects:BTreeMap<_,_>=p.objects.iter().enumerate().map(|(i,(n,_))|(n.clone(),i)).collect();
    let mut facts:Vec<_>=reachable.into_iter().collect();
    facts.sort_by_key(|a|(predicates[&a.predicate],a.terms.iter().map(|n|objects[n]).collect::<Vec<_>>()));
    let numbering:BTreeMap<_,_>=facts.iter().enumerate().map(|(i,a)|(a.clone(),i)).collect();
    let numbers=|atoms:&BTreeSet<Atom>|atoms.iter().filter_map(|a|numbering.get(a).copied()).collect::<State>();
    let mut actions=Vec::new();
    for i in kept{
        let c=&candidates[i];
        stats[c.source][2]+=1;
        let a=&d.actions[c.source];
        actions.push(Action{
            source:c.source,
            name:a.name.clone(),
            args:c.args.clone(),
            cost:a.cost,
            pre:numbers(&c.pre),
            neg:numbers(&c.neg),
            add:numbers(&c.add),
            del:numbers(&c.del)
        });
    }
    let initial_state=initial.iter().filter_map(|a|numbering.get(a).copied()).collect();
    let mut goals=State::new();
    let mut unreachable=Vec::new();
    for a in &p.goals{
        if let Some(&i)=numbering.get(a){
            goals.insert(i);
        }else if fluent.contains(&a.predicate)||!initial.contains(a){
            unreachable.push(a.clone());
        }
    }
    Grounding{
        facts,
        actions,
        initial:initial_state,
        goals,
        unreachable,
        stats,
        fluent:fluent.clone(),
        static_count:p.initial.iter().filter(|a|!fluent.contains(&a.predicate)).count()
    }
}

use std::collections::BTreeSet;
use crate::grounding::{Grounding,State};
pub const INF:i64=1_000_000_000_000;
fn aggregate(values:impl Iterator<Item=i64>,maximum:bool)->i64{
    let mut out=0;
    for v in values{
        if v>=INF{
            return INF;
        }
        if maximum{
            out=out.max(v);
        }else{
            out+=v;
        }
    }
    out
}
pub fn costs(g:&Grounding,s:&State,maximum:bool)->Vec<i64>{
    let mut c=vec![INF;g.facts.len()];
    for &p in s{
        c[p]=0;
    }
    loop{
        let mut changed=false;
        for a in &g.actions{
            let v=aggregate(a.pre.iter().map(|&p|c[p]),maximum);
            if v>=INF{
                continue;
            }
            let v=v+a.cost;
            for &p in &a.add{
                if v<c[p]{
                    c[p]=v;
                    changed=true;
                }
            }
        }
        if !changed{
            return c;
        }
    }
}
pub fn relaxed(g:&Grounding,s:&State)->(i64,Vec<usize>,Vec<usize>){
    let c=costs(g,s,false);
    if g.goals.iter().any(|&p|c[p]>=INF){
        return(INF,Vec::new(),Vec::new());
    }
    let achiever=|p:usize|g.actions.iter().enumerate().filter(|(_,a)|a.add.contains(&p)&&a.pre.iter().all(|&q|c[q]<INF)).min_by_key(|(i,a)|(a.cost+a.pre.iter().map(|&q|c[q]).sum::<i64>(),*i)).unwrap().0;
    let mut chosen=BTreeSet::new();
    let mut pending:Vec<_>=g.goals.difference(s).copied().collect();
    while let Some(p)=pending.pop(){
        let a=achiever(p);
        if chosen.insert(a){
            pending.extend(g.actions[a].pre.difference(s).copied());
        }
    }
    let plan:Vec<_>=chosen.into_iter().collect();
    let helpful=plan.iter().copied().filter(|&a|crate::search::applicable(&g.actions[a],s)).collect();
    let value=plan.iter().map(|&a|g.actions[a].cost).sum();
    (value,plan,helpful)
}
pub fn landmarks(g:&Grounding,s:&State)->Option<State>{
    let mut fact_level=vec![usize::MAX;g.facts.len()];
    for &p in s{
        fact_level[p]=0;
    }
    let mut action_level=vec![usize::MAX;g.actions.len()];
    for k in 0..{
        let mut added=false;
        for(i,a)in g.actions.iter().enumerate(){
            if action_level[i]==usize::MAX&&a.pre.iter().all(|&p|fact_level[p]<=k){
                action_level[i]=k;
                for &p in &a.add{
                    if fact_level[p]==usize::MAX{
                        fact_level[p]=k+1;
                        added=true;
                    }
                }
            }
        }
        if !added{
            break;
        }
    }
    if g.goals.iter().any(|&p|fact_level[p]==usize::MAX){
        return None;
    }
    let mut lm:State=g.goals.difference(s).copied().collect();
    loop{
        let before=lm.len();
        for p in lm.clone(){
            let achievers:Vec<_>=g.actions.iter().enumerate().filter(|(i,a)|action_level[*i]!=usize::MAX&&action_level[*i]+1==fact_level[p]&&a.add.contains(&p)).map(|(_,a)|a).collect();
            let mut candidates=achievers[0].pre.clone();
            for a in &achievers[1..]{
                candidates=candidates.intersection(&a.pre).copied().collect();
            }
            for q in candidates.difference(s){
                if lm.contains(q){
                    continue;
                }
                let mut reachable=s.clone();
                loop{
                    let old=reachable.len();
                    for a in &g.actions{
                        if !a.add.contains(q)&&a.pre.is_subset(&reachable){
                            reachable.extend(&a.add);
                        }
                    }
                    if old==reachable.len(){
                        break;
                    }
                }
                if !g.goals.is_subset(&reachable){
                    lm.insert(*q);
                }
            }
        }
        if lm.len()==before{
            return Some(lm);
        }
    }
}
pub fn value(g:&Grounding,s:&State,name:&str)->i64{
    match name{
        "none"=>0,"goalcount"=>g.goals.difference(s).count()as i64,"hmax"|"hadd"=>{
            let maximum=name=="hmax";
            let c=costs(g,s,maximum);
            aggregate(g.goals.iter().map(|&p|c[p]),maximum)
        },"ff"=>relaxed(g,s).0,_=>landmarks(g,s).map_or(INF,|m|m.len()as i64)
    }
}
pub fn values(g:&Grounding,s:&State)->[i64;5]{
    [value(g,s,"goalcount"),value(g,s,"hmax"),value(g,s,"hadd"),value(g,s,"ff"),value(g,s,"lmcount")]
}

